void ui_ScreenOnThePhone_screen_uninit(lv_obj_t * win,void * p)
{
    lv_obj_t *      ui_ScreenOnThePhone = NULL;

    ui_ScreenOnThePhone = lv_obj_get_user_data(win);

    if (ui_ScreenOnThePhone) {
        uint32_t        is_mute_ul;

        is_mute_ul          = g_audio_is_mute_ul;

        if (is_mute_ul) {
            is_mute_ul          = 0;
            audio_mute_ul(is_mute_ul);
            g_audio_is_mute_ul  = is_mute_ul;
            }

        lv_obj_del_delayed_callback(ui_ScreenOnThePhone,100,lv_obj_del_screen_ready_cb);
        }

    lv_obj_set_user_data(win,NULL);
}



